import json
import re


def parse_provider_output(text):
    text = str(text or "").strip()
    for candidate in [text, text[text.find("{"): text.rfind("}") + 1] if "{" in text and "}" in text else ""]:
        if not candidate:
            continue
        try:
            value = json.loads(candidate)
            return value if isinstance(value, dict) else {}
        except Exception:
            continue
    return {}

